/**
 * `validateLayoutBlocks` is generated by the typia transform, which jest does not run, so this spec exercises the
 * build output. `turbo.json` makes `testunit` depend on this package's `build`.
 */
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { validateLayoutBlocks } = require('../../dist/blocks/validateLayoutBlocks') as {
	validateLayoutBlocks: (blocks: unknown, maxBlocks?: number) => { path: string; expected: string }[];
};

const text = (value: string) => ({ type: 'plain_text', text: value });

it('accepts blocks whose elements leave out appId, blockId and actionId', () => {
	expect(
		validateLayoutBlocks([
			{ type: 'section', text: text('hi'), accessory: { type: 'button', text: text('go'), actionId: 'go' } },
			{ type: 'actions', elements: [{ type: 'button', text: text('go') }] },
			{ type: 'divider' },
		]),
	).toEqual([]);
});

it('reports a block that departs from its type', () => {
	const errors = validateLayoutBlocks([{ type: 'header', text: 'not a text object' }]);

	expect(errors.map(({ path }) => path)).toEqual(expect.arrayContaining(['$input[0].text']));
});

it('reports unknown block types', () => {
	expect(validateLayoutBlocks([{ type: 'bogus' }])).not.toEqual([]);
});

it('reports blocks beyond the limit of the message or of the view', () => {
	const blocks = Array.from({ length: 51 }, () => ({ type: 'divider' }));

	expect(validateLayoutBlocks(blocks).map(({ path }) => path)).toEqual(['$input']);
	expect(validateLayoutBlocks(blocks, 100)).toEqual([]);
});

it('accepts a plan of tasks and reports one with more than 50', () => {
	const task = { task_id: 't', title: 'Step', status: 'pending' };
	const plan = (count: number) => [{ type: 'plan', title: 'Plan', tasks: Array.from({ length: count }, () => task) }];

	expect(validateLayoutBlocks(plan(50))).toEqual([]);
	expect(validateLayoutBlocks(plan(51)).map(({ path }) => path)).toEqual(['$input[0].tasks']);
});

it('reports a task card with an unknown status', () => {
	expect(validateLayoutBlocks([{ type: 'task_card', task_id: 't', title: 'Step', status: 'done' }]).length).toBeGreaterThan(0);
});

it('reports text beyond its limit', () => {
	expect(validateLayoutBlocks([{ type: 'header', text: text('a'.repeat(151)) }]).map(({ path }) => path)).toEqual(['$input[0].text.text']);
});

it.each([
	{ type: 'checkboxes', options: [{ text: text('A'), value: 'a' }] },
	{ type: 'radio_buttons', options: [{ text: text('A'), value: 'a' }] },
	{ type: 'timepicker' },
])('accepts the alternative element name $type', (element) => {
	expect(validateLayoutBlocks([{ type: 'actions', elements: [element] }])).toEqual([]);
});

it('accepts a carousel of cards with buttons that leave out their ids', () => {
	const card = {
		type: 'card',
		hero_image: { type: 'image', image_url: 'https://example.com/a.png', alt_text: 'a' },
		title: text('Card'),
		actions: [{ type: 'button', text: text('go') }],
	};

	expect(validateLayoutBlocks([card, { type: 'carousel', elements: [card] }, { type: 'alert', text: text('hi'), level: 'info' }])).toEqual(
		[],
	);
	expect(validateLayoutBlocks([{ type: 'alert', text: text('hi'), level: 'bogus' }])).not.toEqual([]);
	expect(validateLayoutBlocks([{ type: 'carousel', elements: [{ type: 'divider' }] }])).not.toEqual([]);
});

it('accepts a data table with buttons that leave out their ids and rejects invalid cells', () => {
	const cell = { type: 'raw_text', text: 'a' };
	const table = (rows: unknown[][]) => [{ type: 'data_table', caption: 'Table', rows }];
	const action = { type: 'action_cell', element: { type: 'button', text: text('go') }, fallback: { type: 'raw_number', value: 1 } };
	const rich = { type: 'rich_text', elements: [{ type: 'rich_text_section', elements: [{ type: 'text', text: 'a' }] }] };

	expect(validateLayoutBlocks(table([[cell], [action], [rich], [{ type: 'raw_number', value: 2, text: 'two' }]]))).toEqual([]);
	expect(validateLayoutBlocks(table([[cell], [{ type: 'action_cell', element: { type: 'divider' } }]]))).not.toEqual([]);
	expect(validateLayoutBlocks(table([[cell], [{ type: 'raw_number', value: 'two' }]]))).not.toEqual([]);
	expect(validateLayoutBlocks([{ type: 'data_table', rows: [[cell], [cell]] }])).not.toEqual([]);
});
